import {
  Activity, AlertTriangle, ArrowRight, ArrowUpRight, BarChart3, Bell, CalendarDays,
  Check, CircleHelp, CloudRain, Droplets, FileDown, FileText, FlaskConical, Leaf, Loader2, Menu,
  MessageCircle, MoreHorizontal, Plus, Search, Send, Settings2, Sprout, Sun, Trash2, TrendingUp, Wind,
  X, Zap,
} from 'lucide-react';
import {
  getGetAdvisoryQueryKey, getGetFarmQueryKey, getListAdvisoriesQueryKey,
  getListChatMessagesQueryKey, getListChatSessionsQueryKey, getListFarmsQueryKey,
  useCreateChatSession, useCreateFarm, useCreateZone, useDeleteFarm, useGenerateAdvisory,
  useGetAdvisory, useGetDashboard, useGetFarm, useHealthCheck,
  useListAdvisories, useListChatMessages, useListChatSessions, useListFarms, useSendChatMessage,
} from '@workspace/api-client-react';
