const queryClient = new QueryClient();
const navItems = [
  { href: '/', label: 'Overview', icon: BarChart3 },
  { href: '/farms', label: 'Farms', icon: Sprout },
  { href: '/advisories', label: 'Advisories', icon: FileText },
  { href: '/assistant', label: 'AI assistant', icon: MessageCircle },
  { href: '/analytics', label: 'Analytics', icon: TrendingUp },
];

function cn(...classes: Array<string | false | undefined>) { return classes.filter(Boolean).join(' '); }
function fmtDate(value?: string) { return value ? new Date(value).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) : '—'; }
function titleCase(value?: string) { return (value || '').toLowerCase().replace(/(^|\s)\S/g, (letter) => letter.toUpperCase()); }

function LoadingState({ rows = 3 }: { rows?: number }) {
  return <div className="space-y-3" aria-label="Loading content" data-testid="loading-state">{Array.from({ length: rows }).map((_, i) => <div key={i} className="h-16 animate-pulse rounded-xl bg-muted" />)}</div>;
}
function ErrorState({ message = 'We could not load this field view.', retry }: { message?: string; retry?: () => void }) {
  return <div className="surface flex flex-col items-center justify-center rounded-2xl p-10 text-center" data-testid="error-state"><AlertTriangle className="mb-3 h-7 w-7 text-accent" /><p className="font-semibold">{message}</p><p className="mt-1 text-sm text-muted-foreground">Check your connection and try again.</p>{retry && <button onClick={retry} className="mt-4 rounded-lg bg-primary px-4 py-2 text-sm font-semibold text-primary-foreground" data-testid="button-retry">Try again</button>}</div>;
}
function EmptyState({ title, detail, action }: { title: string; detail: string; action?: React.ReactNode }) {
  return <div className="surface flex min-h-56 flex-col items-center justify-center rounded-2xl p-8 text-center" data-testid="empty-state"><div className="mb-3 rounded-full bg-secondary p-3 text-primary"><Leaf className="h-5 w-5" /></div><p className="font-semibold">{title}</p><p className="mt-1 max-w-sm text-sm text-muted-foreground">{detail}</p>{action && <div className="mt-5">{action}</div>}</div>;
}

function Logo() {
  return <Link href="/" className="flex items-center gap-3" data-testid="link-logo"><span className="grid h-9 w-9 place-items-center rounded-xl bg-accent text-primary-foreground shadow-sm"><Leaf className="h-[18px] w-[18px]" /></span><span><span className="block font-display text-xl leading-none text-sidebar-foreground">AgriMind</span><span className="eyebrow mt-1 block text-sidebar-foreground/55">field intelligence</span></span></Link>;
}
function AppShell({ children }: { children: React.ReactNode }) {
  const [location] = useLocation();
  const [mobileOpen, setMobileOpen] = useState(false);
  const current = navItems.find((item) => item.href === location)?.label || (location.startsWith('/farm') ? 'Farms' : location.startsWith('/advis') ? 'Advisories' : 'Workspace');
  return <div className="grain min-h-[100dvh] bg-background">
    <aside className={cn('fixed inset-y-0 left-0 z-40 flex w-[248px] flex-col bg-sidebar px-5 py-6 text-sidebar-foreground transition-transform duration-300 lg:translate-x-0', mobileOpen ? 'translate-x-0' : '-translate-x-full')} data-testid="sidebar">
      <Logo />
      <div className="mt-10 px-2 eyebrow text-sidebar-foreground/45">Workspace</div>
      <nav className="mt-3 space-y-1" aria-label="Primary navigation">{navItems.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={() => setMobileOpen(false)} className={cn('group flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold text-sidebar-foreground/65 transition-colors hover:bg-sidebar-accent hover:text-sidebar-accent-foreground', location === href && 'bg-sidebar-accent text-sidebar-accent-foreground')} data-testid={`link-nav-${label.toLowerCase().replaceAll(' ', '-')}`}><Icon className={cn('h-[17px] w-[17px]', location === href ? 'text-sidebar-primary' : 'text-sidebar-foreground/45')} />{label}{location === href && <span className="ml-auto h-1.5 w-1.5 rounded-full bg-sidebar-primary" />}</Link>)}</nav>
      <div className="mt-8 px-2 eyebrow text-sidebar-foreground/45">Manage</div>
      <nav className="mt-3 space-y-1"><Link href="/settings" onClick={() => setMobileOpen(false)} className={cn('group flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold text-sidebar-foreground/65 hover:bg-sidebar-accent hover:text-sidebar-accent-foreground', location === '/settings' && 'bg-sidebar-accent text-sidebar-accent-foreground')} data-testid="link-nav-settings"><Settings2 className="h-[17px] w-[17px] text-sidebar-foreground/45" />Settings</Link></nav>
      <div className="mt-auto rounded-2xl border border-sidebar-border bg-sidebar-accent/50 p-4"><div className="flex items-center gap-2 text-xs font-semibold"><span className="h-2 w-2 rounded-full bg-[#a7d56b]" />All systems operational</div><p className="mt-2 text-[11px] leading-relaxed text-sidebar-foreground/50">Your field data is syncing normally.</p></div>
      <div className="mt-5 flex items-center gap-3 border-t border-sidebar-border pt-5"><span className="grid h-8 w-8 place-items-center rounded-full bg-[#be8264] text-xs font-bold text-sidebar-foreground">JM</span><div className="min-w-0"><p className="truncate text-xs font-bold">Jordan Mitchell</p><p className="truncate text-[11px] text-sidebar-foreground/45">Farm manager</p></div><MoreHorizontal className="ml-auto h-4 w-4 text-sidebar-foreground/45" /></div>
    </aside>
    {mobileOpen && <button aria-label="Close navigation" onClick={() => setMobileOpen(false)} className="fixed inset-0 z-30 bg-sidebar/30 lg:hidden" data-testid="button-close-navigation" />}
    <main className="min-h-[100dvh] lg:pl-[248px]"><header className="sticky top-0 z-20 flex h-[72px] items-center justify-between border-b border-border/70 bg-background/90 px-5 backdrop-blur-md sm:px-8"><div className="flex items-center gap-3"><button onClick={() => setMobileOpen(true)} className="rounded-lg p-2 hover:bg-muted lg:hidden" aria-label="Open navigation" data-testid="button-open-navigation"><Menu className="h-5 w-5" /></button><div><p className="eyebrow text-muted-foreground">AgriMind / {current}</p><p className="mt-1 hidden text-xs text-muted-foreground sm:block">Good morning, Jordan. Here is your field readout.</p></div></div><div className="flex items-center gap-2 sm:gap-4"><button className="relative rounded-lg p-2 text-muted-foreground hover:bg-muted hover:text-foreground" aria-label="Notifications" data-testid="button-notifications"><Bell className="h-[18px] w-[18px]" /><span className="absolute right-1.5 top-1.5 h-1.5 w-1.5 rounded-full bg-accent" /></button><div className="hidden h-5 w-px bg-border sm:block" /><span className="hidden text-xs font-semibold text-muted-foreground sm:block">Field season 2024</span><span className="grid h-8 w-8 place-items-center rounded-full bg-primary text-xs font-bold text-primary-foreground">JM</span></div></header><div className="mx-auto max-w-[1440px] px-5 py-7 sm:px-8 lg:px-10">{children}</div></main>
  </div>;
}

function PageHeading({ eyebrow, title, detail, action }: { eyebrow: string; title: string; detail?: string; action?: React.ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="eyebrow text-primary">{eyebrow}</p><h1 className="mt-2 font-display text-4xl leading-[.95] tracking-tight sm:text-5xl" data-testid="text-page-title">{title}</h1>{detail && <p className="mt-3 max-w-xl text-sm leading-relaxed text-muted-foreground">{detail}</p>}</div>{action && <div className="shrink-0">{action}</div>}</div>;
}
function Button({ children, onClick, variant = 'primary', type = 'button', className = '', disabled = false }: { children: React.ReactNode; onClick?: () => void; variant?: 'primary' | 'outline' | 'ghost' | 'danger'; type?: 'button' | 'submit'; className?: string; disabled?: boolean }) {
  return <button type={type} onClick={onClick} disabled={disabled} className={cn('inline-flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-bold transition-all active:scale-[.98] disabled:cursor-not-allowed disabled:opacity-50', variant === 'primary' && 'bg-primary text-primary-foreground shadow-sm hover:-translate-y-0.5 hover:shadow-md', variant === 'outline' && 'border border-border bg-card text-foreground hover:border-primary/40 hover:bg-secondary', variant === 'ghost' && 'text-muted-foreground hover:bg-muted hover:text-foreground', variant === 'danger' && 'border border-destructive/20 bg-destructive/5 text-destructive hover:bg-destructive/10', className)}>{children}</button>;
}
function Metric({ label, value, suffix, trend, tone = 'green' }: { label: string; value: string | number; suffix?: string; trend?: string; tone?: 'green' | 'amber' | 'blue' }) {
  return <div className="surface rounded-2xl p-5" data-testid={`metric-${label.toLowerCase().replaceAll(' ', '-')}`}><div className="flex items-start justify-between"><span className="eyebrow text-muted-foreground">{label}</span><span className={cn('h-2 w-2 rounded-full', tone === 'green' ? 'bg-primary' : tone === 'amber' ? 'bg-accent' : 'bg-chart-3')} /></div><div className="mt-4 flex items-baseline gap-1"><span className="font-display text-4xl">{value}</span>{suffix && <span className="text-sm text-muted-foreground">{suffix}</span>}</div>{trend && <div className="mt-2 flex items-center gap-1 text-xs font-semibold text-primary"><ArrowUpRight className="h-3.5 w-3.5" />{trend}</div>}</div>;
}
function Panel({ title, eyebrow, children, action }: { title: string; eyebrow?: string; children: React.ReactNode; action?: React.ReactNode }) {
  return <section className="surface rounded-2xl p-5 sm:p-6"><div className="mb-5 flex items-start justify-between gap-3"><div>{eyebrow && <p className="eyebrow text-muted-foreground">{eyebrow}</p>}<h2 className="mt-1 text-base font-bold">{title}</h2></div>{action}</div>{children}</section>;
}
function StatusPill({ value }: { value: string }) {
  const good = ['healthy', 'active', 'operational', 'on track'].includes(value.toLowerCase());
  const warning = ['watch', 'medium', 'pending'].includes(value.toLowerCase());
  return <span className={cn('inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-bold capitalize', good ? 'bg-primary/10 text-primary' : warning ? 'bg-accent/15 text-[#9a6116]' : 'bg-destructive/10 text-destructive')}><span className="h-1.5 w-1.5 rounded-full bg-current" />{value.toLowerCase()}</span>;
}

function Dashboard() {
  const dashboard = useGetDashboard();
  const summary = dashboard.data as DashboardSummary | undefined;
  if (dashboard.isLoading) return <><PageHeading eyebrow="Field overview" title="Your fields, in focus." detail="A clear morning readout across farms, crop health, and the decisions waiting on you." /><LoadingState rows={4} /></>;
  if (dashboard.isError || !summary) return <><PageHeading eyebrow="Field overview" title="Your fields, in focus." /><ErrorState retry={() => dashboard.refetch()} /></>;
  return <div className="fade-up"><PageHeading eyebrow="Field overview · Tuesday, June 18" title="Your fields, in focus." detail="A clear morning readout across farms, crop health, and the decisions waiting on you." action={<Link href="/advisory/new" className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground shadow-sm transition-all hover:-translate-y-0.5 hover:shadow-md" data-testid="link-new-advisory"><Plus className="h-4 w-4" />New advisory</Link>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Active farms" value={summary.farmCount} trend="All reporting" /><Metric label="Open alerts" value={summary.activeAlerts} tone="amber" trend={summary.activeAlerts ? 'Needs a look' : 'Clear today'} /><Metric label="Advisories" value={summary.advisoryCount} tone="blue" trend="This season" /><Metric label="Soil readiness" value={summary.soilScore} suffix="/ 100" trend="↑ 4 pts this month" /></div><div className="mt-4 grid gap-4 xl:grid-cols-[1.35fr_.65fr]"><Panel title="Crop outlook" eyebrow="Yield potential" action={<Link href="/analytics" className="text-xs font-bold text-primary hover:underline" data-testid="link-dashboard-analytics">View analytics <ArrowRight className="ml-1 inline h-3 w-3" /></Link>}><div className="space-y-5">{(summary.yieldData || []).slice(0, 4).map((item, index) => <div key={item.label} data-testid={`yield-row-${index}`}><div className="mb-2 flex items-center justify-between text-sm"><span className="font-semibold">{item.label}</span><span className="font-mono text-xs text-muted-foreground">{item.value}% <span className="text-primary">/ {item.target}% target</span></span></div><div className="h-2 overflow-hidden rounded-full bg-secondary"><div className="h-full rounded-full bg-primary transition-all" style={{ width: `${Math.min(item.value, 100)}%` }} /></div></div>)}</div></Panel><Panel title="Weather window" eyebrow={summary.weather.location}><div className="flex items-start justify-between"><div><span className="font-display text-5xl">{summary.weather.temperature}°</span><p className="mt-1 text-sm font-semibold">{summary.weather.condition}</p></div><div className="grid h-12 w-12 place-items-center rounded-2xl bg-accent/15 text-[#9a6116]"><Sun className="h-6 w-6" /></div></div><div className="mt-6 grid grid-cols-2 gap-3 border-t border-border pt-4 text-xs"><div><span className="block text-muted-foreground">Humidity</span><strong className="mt-1 block text-sm">{summary.weather.humidity}%</strong></div><div><span className="block text-muted-foreground">Rain chance</span><strong className="mt-1 block text-sm">{summary.weather.rainChance}%</strong></div></div><div className="mt-5 flex gap-2 overflow-hidden">{(summary.weather.forecast || []).slice(0, 4).map((day) => <div key={day.day} className="min-w-[58px] rounded-xl bg-muted/70 p-2 text-center"><span className="block text-[10px] text-muted-foreground">{day.day}</span><CloudRain className="mx-auto my-2 h-4 w-4 text-chart-3" /><span className="font-mono text-[10px]">{day.high}°</span></div>)}</div></Panel></div><div className="mt-4 grid gap-4 lg:grid-cols-[.85fr_1.15fr]"><Panel title="Nutrient signals" eyebrow="Latest soil samples"><div className="grid grid-cols-3 gap-3">{(summary.nutrientData || []).map((item) => <div key={item.label} className="rounded-xl bg-muted/70 p-3"><span className="eyebrow text-muted-foreground">{item.label}</span><p className="mt-2 font-display text-2xl">{item.value}</p><p className="mt-1 text-[11px] text-muted-foreground">Target {item.target}</p><div className="mt-3 h-1 rounded-full bg-border"><div className="h-full rounded-full bg-accent" style={{ width: `${Math.min(item.value / item.target * 100, 100)}%` }} /></div></div>)}</div></Panel><Panel title="Recent activity" eyebrow="Across your workspace" action={<Link href="/advisories" className="text-xs font-bold text-primary hover:underline" data-testid="link-dashboard-history">View history</Link>}><div className="divide-y divide-border">{(summary.activities || []).slice(0, 4).map((item) => <div key={item.id} className="flex items-center gap-3 py-3 first:pt-0 last:pb-0" data-testid={`activity-${item.id}`}><div className="grid h-8 w-8 shrink-0 place-items-center rounded-lg bg-secondary text-primary">{item.type === 'alert' ? <AlertTriangle className="h-4 w-4" /> : item.type === 'weather' ? <CloudRain className="h-4 w-4" /> : <Activity className="h-4 w-4" />}</div><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{item.title}</p><p className="truncate text-xs text-muted-foreground">{item.detail}</p></div><span className="shrink-0 font-mono text-[10px] text-muted-foreground">{item.time}</span></div>)}</div></Panel></div></div>;
}

function FarmCard({ farm, onDelete }: { farm: Farm; onDelete: (id: string) => void }) {
  return <div className="surface interactive group rounded-2xl p-5" data-testid={`card-farm-${farm.id}`}><div className="flex items-start justify-between"><Link href={`/farms/${farm.id}`} className="min-w-0" data-testid={`link-farm-${farm.id}`}><p className="eyebrow text-primary">{farm.location}</p><h2 className="mt-1 truncate text-lg font-bold">{farm.name}</h2></Link><button onClick={() => onDelete(farm.id)} className="rounded-lg p-1.5 text-muted-foreground opacity-0 transition-opacity hover:bg-destructive/10 hover:text-destructive group-hover:opacity-100" aria-label={`Delete ${farm.name}`} data-testid={`button-delete-farm-${farm.id}`}><Trash2 className="h-4 w-4" /></button></div><div className="mt-5 flex items-end justify-between"><div><p className="text-xs text-muted-foreground">Primary crop</p><p className="mt-1 text-sm font-bold">{farm.crop}</p></div><div className="text-right"><p className="text-xs text-muted-foreground">Field health</p><p className="mt-1 font-mono text-lg font-medium text-primary">{farm.healthScore}<span className="text-xs text-muted-foreground"> / 100</span></p></div></div><div className="mt-4 h-1.5 overflow-hidden rounded-full bg-secondary"><div className="h-full rounded-full bg-primary" style={{ width: `${farm.healthScore}%` }} /></div><div className="mt-5 grid grid-cols-3 gap-2 border-t border-border pt-4 text-xs"><div><span className="block text-muted-foreground">Area</span><strong className="mt-1 block">{farm.area} ha</strong></div><div><span className="block text-muted-foreground">Moisture</span><strong className="mt-1 block">{farm.moisture}%</strong></div><div><span className="block text-muted-foreground">Zones</span><strong className="mt-1 block">{farm.zones?.length || 0}</strong></div></div></div>;
}
function FarmForm({ onClose, onCreated }: { onClose: () => void; onCreated: () => void }) {
  const create = useCreateFarm();
  const [form, setForm] = useState({ name: '', location: '', area: '', crop: '', irrigation: 'Drip irrigation' });
  const submit = (event: React.FormEvent) => { event.preventDefault(); create.mutate({ data: { name: form.name, location: form.location, area: Number(form.area), crop: form.crop, irrigation: form.irrigation } }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getListFarmsQueryKey() }); onCreated(); } }); };
  const field = (key: keyof typeof form, label: string, type = 'text', placeholder = '') => <label className="block"><span className="mb-1.5 block text-xs font-bold text-muted-foreground">{label}</span><input required value={form[key]} type={type} placeholder={placeholder} onChange={(event) => setForm({ ...form, [key]: event.target.value })} className="h-11 w-full rounded-xl border border-input bg-background px-3 text-sm outline-none ring-primary/20 transition focus:ring-4" data-testid={`input-farm-${key}`} /></label>;
  return <div className="fixed inset-0 z-50 grid place-items-center bg-sidebar/35 p-4 backdrop-blur-sm"><form onSubmit={submit} className="surface max-h-[90vh] w-full max-w-lg overflow-auto rounded-2xl p-6 shadow-xl" data-testid="form-create-farm"><div className="flex items-start justify-between"><div><p className="eyebrow text-primary">Farm inventory</p><h2 className="mt-1 font-display text-3xl">Add a farm</h2></div><button type="button" onClick={onClose} className="rounded-lg p-2 text-muted-foreground hover:bg-muted" aria-label="Close form" data-testid="button-close-farm-form"><X className="h-4 w-4" /></button></div><div className="mt-6 space-y-4">{field('name', 'Farm name', 'text', 'e.g. North Orchard')}{field('location', 'Location', 'text', 'e.g. Salinas, CA')}<div className="grid gap-4 sm:grid-cols-2">{field('area', 'Area (hectares)', 'number', '0.0')}{field('crop', 'Primary crop', 'text', 'e.g. Romaine lettuce')}</div><label className="block"><span className="mb-1.5 block text-xs font-bold text-muted-foreground">Irrigation</span><select value={form.irrigation} onChange={(event) => setForm({ ...form, irrigation: event.target.value })} className="h-11 w-full rounded-xl border border-input bg-background px-3 text-sm" data-testid="select-farm-irrigation"><option>Drip irrigation</option><option>Center pivot</option><option>Rainfed</option><option>Sprinkler</option></select></label></div><div className="mt-7 flex justify-end gap-2"><Button variant="ghost" onClick={onClose}>Cancel</Button><Button type="submit" disabled={create.isPending}>{create.isPending && <Loader2 className="h-4 w-4 animate-spin" />}Save farm</Button></div>{create.isError && <p className="mt-3 text-right text-xs text-destructive">Could not save this farm. Please try again.</p>}</form></div>;
}
function Farms() {
  const farms = useListFarms();
  const del = useDeleteFarm();
  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState('');
  const data = ((farms.data as Farm[] | undefined) || []).filter((farm) => `${farm.name} ${farm.location} ${farm.crop}`.toLowerCase().includes(search.toLowerCase()));
  const remove = (id: string) => { if (window.confirm('Remove this farm from your inventory?')) del.mutate({ farmId: id }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListFarmsQueryKey() }) }); };
  return <div className="fade-up"><PageHeading eyebrow="Farm inventory" title="The land you look after." detail="A living register of your farms, their crop mix, and the signals worth following." action={<Button onClick={() => setOpen(true)}><Plus className="h-4 w-4" />Add farm</Button>} /><div className="mb-5 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div className="relative w-full sm:max-w-xs"><Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search farms" className="h-10 w-full rounded-xl border border-input bg-card pl-9 pr-3 text-sm outline-none focus:ring-4 focus:ring-primary/10" data-testid="input-search-farms" /></div><p className="font-mono text-xs text-muted-foreground">{data.length} of {farms.data?.length || 0} farms</p></div>{farms.isLoading ? <LoadingState /> : farms.isError ? <ErrorState retry={() => farms.refetch()} /> : data.length === 0 ? <EmptyState title={search ? 'No farms match that search' : 'Your inventory is ready for its first farm'} detail={search ? 'Try another farm name, crop, or location.' : 'Add a farm to start tracking crop health and field signals.'} action={!search && <Button onClick={() => setOpen(true)}><Plus className="h-4 w-4" />Add your first farm</Button>} /> : <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{data.map((farm) => <FarmCard key={farm.id} farm={farm} onDelete={remove} />)}</div>}{open && <FarmForm onClose={() => setOpen(false)} onCreated={() => setOpen(false)} />}</div>;
}

function FarmDetail() {
  const { farmId = '' } = useParams<{ farmId: string }>();
  const farm = useGetFarm(farmId, { query: { enabled: !!farmId, queryKey: getGetFarmQueryKey(farmId) } });
  const createZone = useCreateZone();
  const [zoneForm, setZoneForm] = useState({ name: '', crop: '', area: '', stage: 'Vegetative' });
  const [adding, setAdding] = useState(false);
  const data = farm.data as Farm | undefined;
  const submitZone = (event: React.FormEvent) => { event.preventDefault(); createZone.mutate({ farmId, data: { name: zoneForm.name, crop: zoneForm.crop, area: Number(zoneForm.area), stage: zoneForm.stage } }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getGetFarmQueryKey(farmId) }); setAdding(false); setZoneForm({ name: '', crop: '', area: '', stage: 'Vegetative' }); } }); };
  if (farm.isLoading) return <LoadingState rows={5} />;
  if (farm.isError || !data) return <ErrorState message="This farm could not be found." retry={() => farm.refetch()} />;
  return <div className="fade-up"><Link href="/farms" className="mb-6 inline-flex items-center gap-2 text-xs font-bold text-muted-foreground hover:text-primary" data-testid="link-back-farms"><ArrowRight className="h-3 w-3 rotate-180" />All farms</Link><PageHeading eyebrow={`${data.location} · ${data.area} hectares`} title={data.name} detail={`${data.crop} · ${data.irrigation || 'Irrigation not recorded'}`} action={<Link href="/advisory/new" className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground" data-testid="link-farm-advisory"><Zap className="h-4 w-4" />Create advisory</Link>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Field health" value={data.healthScore} suffix="/ 100" trend="Stable this week" /><Metric label="Moisture" value={data.moisture} suffix="%" tone="blue" trend="Within target" /><Metric label="Crop varieties" value={data.cropCount} trend="Across zones" /><Metric label="Zones" value={data.zones?.length || 0} tone="amber" trend="Mapped fields" /></div><div className="mt-4 grid gap-4 xl:grid-cols-[1.2fr_.8fr]"><Panel title="Zones and crop stages" eyebrow="Field map / inventory" action={<Button variant="outline" onClick={() => setAdding(!adding)}><Plus className="h-4 w-4" />Add zone</Button>}>{adding && <form onSubmit={submitZone} className="mb-5 grid gap-3 rounded-xl bg-muted/70 p-4 sm:grid-cols-4" data-testid="form-create-zone"><input required placeholder="Zone name" value={zoneForm.name} onChange={(event) => setZoneForm({ ...zoneForm, name: event.target.value })} className="h-10 rounded-lg border border-input bg-background px-3 text-sm" data-testid="input-zone-name" /><input required placeholder="Crop" value={zoneForm.crop} onChange={(event) => setZoneForm({ ...zoneForm, crop: event.target.value })} className="h-10 rounded-lg border border-input bg-background px-3 text-sm" data-testid="input-zone-crop" /><input required type="number" placeholder="Area ha" value={zoneForm.area} onChange={(event) => setZoneForm({ ...zoneForm, area: event.target.value })} className="h-10 rounded-lg border border-input bg-background px-3 text-sm" data-testid="input-zone-area" /><Button type="submit" disabled={createZone.isPending}>{createZone.isPending ? <Loader2 className="h-4 w-4 animate-spin" /> : <Check className="h-4 w-4" />}Save zone</Button></form>}<div className="divide-y divide-border">{(data.zones || []).map((zone: Zone) => <div key={zone.id} className="flex flex-wrap items-center gap-4 py-4 first:pt-0 last:pb-0" data-testid={`row-zone-${zone.id}`}><div className="grid h-10 w-10 place-items-center rounded-xl bg-secondary text-primary"><Sprout className="h-5 w-5" /></div><div className="min-w-[120px] flex-1"><p className="text-sm font-bold">{zone.name}</p><p className="mt-1 text-xs text-muted-foreground">{zone.crop} · {zone.area} ha</p></div><span className="rounded-full bg-muted px-2.5 py-1 text-[11px] font-bold text-muted-foreground">{zone.stage || 'Unstaged'}</span><StatusPill value={zone.status || 'Active'} /></div>)}</div></Panel><Panel title="Health readout" eyebrow="Signal summary"><div className="relative mx-auto flex h-48 w-48 items-center justify-center rounded-full" style={{ background: `conic-gradient(hsl(var(--primary)) ${data.healthScore * 3.6}deg, hsl(var(--secondary)) 0deg)` }}><div className="grid h-36 w-36 place-items-center rounded-full bg-card"><div className="text-center"><span className="font-display text-5xl">{data.healthScore}</span><span className="block text-[10px] text-muted-foreground">out of 100</span></div></div></div><div className="mt-5 space-y-3 border-t border-border pt-4 text-sm"><div className="flex justify-between"><span className="text-muted-foreground">Overall status</span><StatusPill value={data.status || 'Healthy'} /></div><div className="flex justify-between"><span className="text-muted-foreground">Coordinates</span><span className="font-mono text-xs">{data.latitude?.toFixed(3) || '—'}, {data.longitude?.toFixed(3) || '—'}</span></div></div></Panel></div></div>;
}

function NewAdvisory() {
  const farms = useListFarms();
  const generate = useGenerateAdvisory();
  const [, setLocation] = useLocation();
  const [step, setStep] = useState(1);
  const [form, setForm] = useState({ farmId: '', crop: '', growthStage: 'Vegetative', symptoms: '', ph: '', nitrogen: '', phosphorus: '', potassium: '', moisture: '', language: 'English' });
  const update = (key: keyof typeof form, value: string) => setForm((current) => ({ ...current, [key]: value }));
  const submit = () => { generate.mutate({ data: { farmId: form.farmId, crop: form.crop, growthStage: form.growthStage, symptoms: form.symptoms.split(',').map((item) => item.trim()).filter(Boolean), ph: form.ph ? Number(form.ph) : undefined, nitrogen: form.nitrogen ? Number(form.nitrogen) : undefined, phosphorus: form.phosphorus ? Number(form.phosphorus) : undefined, potassium: form.potassium ? Number(form.potassium) : undefined, moisture: form.moisture ? Number(form.moisture) : undefined, language: form.language } }, { onSuccess: (advisory) => { queryClient.invalidateQueries({ queryKey: getListAdvisoriesQueryKey() }); setLocation(`/advisories/${advisory.id}`); } }); };
  const chosenFarm = (farms.data as Farm[] | undefined)?.find((farm) => farm.id === form.farmId);
  const control = (key: keyof typeof form, label: string, placeholder: string, type = 'text') => <label className="block"><span className="mb-1.5 block text-xs font-bold text-muted-foreground">{label}</span><input type={type} value={form[key]} onChange={(event) => update(key, event.target.value)} placeholder={placeholder} className="h-11 w-full rounded-xl border border-input bg-background px-3 text-sm outline-none focus:ring-4 focus:ring-primary/10" data-testid={`input-advisory-${key}`} /></label>;
  return <div className="mx-auto max-w-4xl fade-up"><Link href="/advisories" className="mb-6 inline-flex items-center gap-2 text-xs font-bold text-muted-foreground hover:text-primary" data-testid="link-back-advisories"><ArrowRight className="h-3 w-3 rotate-180" />Advisory history</Link><PageHeading eyebrow="Guided intake" title="Read the field before you act." detail="Share the conditions as you see them. AgriMind will return a grounded action plan, not a generic answer." /><div className="mb-7 flex items-center gap-2">{[1, 2, 3].map((item) => <div key={item} className="flex flex-1 items-center gap-2"><span className={cn('grid h-8 w-8 shrink-0 place-items-center rounded-full text-xs font-bold', step >= item ? 'bg-primary text-primary-foreground' : 'bg-secondary text-muted-foreground')}>{step > item ? <Check className="h-4 w-4" /> : item}</span><span className={cn('hidden text-xs font-bold sm:block', step >= item ? 'text-foreground' : 'text-muted-foreground')}>{item === 1 ? 'Field context' : item === 2 ? 'Visible signals' : 'Soil readout'}</span>{item < 3 && <div className={cn('h-px flex-1', step > item ? 'bg-primary' : 'bg-border')} />}</div>)}</div><div className="surface rounded-2xl p-6 sm:p-8">{step === 1 && <div className="fade-up"><h2 className="font-display text-3xl">Which field are we reading?</h2><p className="mt-2 text-sm text-muted-foreground">Start with the crop and its current stage.</p><div className="mt-7 grid gap-4 sm:grid-cols-2"><label className="block"><span className="mb-1.5 block text-xs font-bold text-muted-foreground">Farm</span><select value={form.farmId} onChange={(event) => update('farmId', event.target.value)} className="h-11 w-full rounded-xl border border-input bg-background px-3 text-sm" data-testid="select-advisory-farm"><option value="">Choose a farm</option>{(farms.data as Farm[] | undefined)?.map((farm) => <option key={farm.id} value={farm.id}>{farm.name} · {farm.location}</option>)}</select></label>{control('crop', 'Crop', chosenFarm?.crop || 'e.g. Romaine lettuce')}<label className="block"><span className="mb-1.5 block text-xs font-bold text-muted-foreground">Growth stage</span><select value={form.growthStage} onChange={(event) => update('growthStage', event.target.value)} className="h-11 w-full rounded-xl border border-input bg-background px-3 text-sm" data-testid="select-advisory-stage"><option>Seedling</option><option>Vegetative</option><option>Flowering</option><option>Fruit development</option><option>Pre-harvest</option></select></label></div><div className="mt-8 flex justify-end"><Button onClick={() => setStep(2)} disabled={!form.farmId || !form.crop}>Continue <ArrowRight className="h-4 w-4" /></Button></div></div>}{step === 2 && <div className="fade-up"><h2 className="font-display text-3xl">What are you seeing?</h2><p className="mt-2 text-sm text-muted-foreground">Use plain field language. Separate observations with commas.</p><label className="mt-7 block"><span className="mb-1.5 block text-xs font-bold text-muted-foreground">Symptoms and observations</span><textarea value={form.symptoms} onChange={(event) => update('symptoms', event.target.value)} rows={5} placeholder="e.g. pale leaves, curling at the edges, slow growth" className="w-full resize-none rounded-xl border border-input bg-background p-3 text-sm outline-none focus:ring-4 focus:ring-primary/10" data-testid="textarea-advisory-symptoms" /></label><div className="mt-8 flex justify-between"><Button variant="ghost" onClick={() => setStep(1)}>Back</Button><Button onClick={() => setStep(3)} disabled={!form.symptoms}>Continue <ArrowRight className="h-4 w-4" /></Button></div></div>}{step === 3 && <div className="fade-up"><h2 className="font-display text-3xl">Add what the soil tells you.</h2><p className="mt-2 text-sm text-muted-foreground">Optional measurements help narrow the recommendation. Leave blank if you do not have a recent sample.</p><div className="mt-7 grid gap-4 sm:grid-cols-2">{control('ph', 'Soil pH', 'e.g. 6.4', 'number')}{control('moisture', 'Moisture %', 'e.g. 42', 'number')}{control('nitrogen', 'Nitrogen (ppm)', 'e.g. 36', 'number')}{control('phosphorus', 'Phosphorus (ppm)', 'e.g. 24', 'number')}{control('potassium', 'Potassium (ppm)', 'e.g. 180', 'number')}</div><div className="mt-8 flex justify-between"><Button variant="ghost" onClick={() => setStep(2)}>Back</Button><Button onClick={submit} disabled={generate.isPending}>{generate.isPending ? <><Loader2 className="h-4 w-4 animate-spin" />Reading field</> : <><Zap className="h-4 w-4" />Generate advisory</>}</Button></div>{generate.isError && <p className="mt-3 text-right text-xs text-destructive">The advisory could not be generated. Review the field details and try again.</p>}</div>}</div></div>;
}

function Advisories() {
  const [search, setSearch] = useState('');
  const [urgency, setUrgency] = useState('');
  const params = urgency ? { urgency: urgency as 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL' } : undefined;
  const advisories = useListAdvisories(params, { query: { queryKey: getListAdvisoriesQueryKey(params) } });
  const data = ((advisories.data as Advisory[] | undefined) || []).filter((item) => `${item.farm} ${item.crop} ${item.diagnosis} ${item.category}`.toLowerCase().includes(search.toLowerCase()));
  return <div className="fade-up"><PageHeading eyebrow="Advisory history" title="Decisions, with a paper trail." detail="Every field read stays here, so you can see what changed and why." action={<Link href="/advisory/new" className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground" data-testid="link-history-new-advisory"><Plus className="h-4 w-4" />New advisory</Link>} /><div className="mb-5 flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search farm, crop, or diagnosis" className="h-10 w-full rounded-xl border border-input bg-card pl-9 pr-3 text-sm outline-none focus:ring-4 focus:ring-primary/10" data-testid="input-search-advisories" /></div><select value={urgency} onChange={(event) => setUrgency(event.target.value)} className="h-10 rounded-xl border border-input bg-card px-3 text-sm sm:w-44" data-testid="select-filter-urgency"><option value="">All urgencies</option><option value="CRITICAL">Critical</option><option value="HIGH">High</option><option value="MEDIUM">Medium</option><option value="LOW">Low</option></select></div>{advisories.isLoading ? <LoadingState rows={5} /> : advisories.isError ? <ErrorState retry={() => advisories.refetch()} /> : data.length === 0 ? <EmptyState title="No advisories yet" detail="Your generated field reads will appear here." action={<Link href="/advisory/new" className="inline-flex rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground" data-testid="link-empty-new-advisory">Start a field read</Link>} /> : <div className="surface overflow-hidden rounded-2xl"><div className="hidden grid-cols-[1.2fr_1fr_.8fr_.7fr_100px] gap-4 border-b border-border bg-muted/50 px-5 py-3 text-[10px] font-bold uppercase tracking-wider text-muted-foreground md:grid"><span>Field read</span><span>Diagnosis</span><span>Confidence</span><span>Created</span><span /></div>{data.map((item) => <Link href={`/advisories/${item.id}`} key={item.id} className="grid gap-3 border-b border-border px-5 py-4 transition-colors last:border-0 hover:bg-muted/40 md:grid-cols-[1.2fr_1fr_.8fr_.7fr_100px] md:items-center md:gap-4" data-testid={`row-advisory-${item.id}`}><div><div className="flex items-center gap-2"><span className="font-bold">{item.crop}</span><StatusPill value={item.urgency} /></div><p className="mt-1 text-xs text-muted-foreground">{item.farm} · {item.category}</p></div><p className="line-clamp-2 text-sm text-muted-foreground">{item.diagnosis}</p><div><span className="font-mono text-sm font-medium">{item.confidence}%</span><div className="mt-1 h-1 w-20 rounded-full bg-secondary"><div className="h-full rounded-full bg-primary" style={{ width: `${item.confidence}%` }} /></div></div><span className="text-xs text-muted-foreground">{fmtDate(item.createdAt)}</span><span className="hidden justify-end text-primary md:flex"><ArrowRight className="h-4 w-4" /></span></Link>)}</div>}</div>;
}

function AdvisoryDetail() {
  const { advisoryId = '' } = useParams<{ advisoryId: string }>();
  const query = useGetAdvisory(advisoryId, { query: { enabled: !!advisoryId, queryKey: getGetAdvisoryQueryKey(advisoryId) } });
  const item = query.data as Advisory | undefined;
  if (query.isLoading) return <LoadingState rows={6} />;
  if (query.isError || !item) return <ErrorState message="This advisory is not available." retry={() => query.refetch()} />;
  return <div className="fade-up"><Link href="/advisories" className="mb-6 inline-flex items-center gap-2 text-xs font-bold text-muted-foreground hover:text-primary" data-testid="link-back-advisory-history"><ArrowRight className="h-3 w-3 rotate-180" />Advisory history</Link><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="eyebrow text-primary">{item.farm} · {fmtDate(item.createdAt)}</p><h1 className="mt-2 max-w-3xl font-display text-4xl leading-[.95] tracking-tight sm:text-5xl">{item.crop}: {item.category}</h1><p className="mt-3 text-sm text-muted-foreground">Field diagnosis generated from your observations and soil readout.</p></div><Button variant="outline" onClick={() => window.print()}><FileDown className="h-4 w-4" />Export report</Button></div><div className="mt-7 grid gap-4 sm:grid-cols-3"><Metric label="Confidence" value={item.confidence} suffix="%" trend="Signal match" /><Metric label="Yield potential" value={item.forecast.yieldPotential} suffix="%" tone="blue" trend="Current outlook" /><Metric label="Urgency" value={titleCase(item.urgency)} tone="amber" trend="Action priority" /></div><div className="mt-4 grid gap-4 xl:grid-cols-[1.1fr_.9fr]"><Panel title="Field diagnosis" eyebrow="What the signals suggest"><p className="text-[15px] leading-7 text-muted-foreground">{item.summary}</p><div className="mt-6 rounded-xl border-l-2 border-accent bg-accent/10 p-4"><p className="eyebrow text-[#9a6116]">Diagnosis</p><p className="mt-2 text-sm font-semibold leading-relaxed">{item.diagnosis}</p></div></Panel><Panel title="Forecast window" eyebrow="What to watch next"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-primary/10 text-primary"><CalendarDays className="h-5 w-5" /></div><div><p className="text-xs text-muted-foreground">Harvest window</p><p className="mt-1 font-bold">{item.forecast.harvestWindow}</p></div></div><div className="mt-5 border-t border-border pt-4"><p className="eyebrow text-muted-foreground">Risk signals</p><ul className="mt-3 space-y-2">{item.forecast.risks.map((risk) => <li key={risk} className="flex gap-2 text-sm"><AlertTriangle className="mt-0.5 h-4 w-4 shrink-0 text-accent" />{risk}</li>)}</ul></div></Panel></div><div className="mt-4 grid gap-4 lg:grid-cols-[1fr_1fr]"><Panel title="Recommended actions" eyebrow="In order of impact"><ol className="space-y-3">{item.actionPlan.map((action, index) => <li key={action} className="flex gap-3 text-sm leading-relaxed"><span className="grid h-6 w-6 shrink-0 place-items-center rounded-full bg-primary text-xs font-bold text-primary-foreground">{index + 1}</span><span>{action}</span></li>)}</ol></Panel><Panel title="Soil readout" eyebrow="Latest available measurements"><div className="grid grid-cols-2 gap-3 sm:grid-cols-4">{[['pH', item.soil.ph, ''], ['Nitrogen', item.soil.nitrogen, 'ppm'], ['Phosphorus', item.soil.phosphorus, 'ppm'], ['Potassium', item.soil.potassium, 'ppm']].map(([label, value, suffix]) => <div key={String(label)} className="rounded-xl bg-muted/70 p-3"><span className="eyebrow text-muted-foreground">{label}</span><p className="mt-2 font-display text-2xl">{value}</p><span className="text-[11px] text-muted-foreground">{suffix || 'acidity'}</span></div>)}</div></Panel></div></div>;
}

function Assistant() {
  const sessions = useListChatSessions();
  const createSession = useCreateChatSession();
  const send = useSendChatMessage();
  const [activeId, setActiveId] = useState('');
  const [draft, setDraft] = useState('');
  const list = (sessions.data as ChatSession[] | undefined) || [];
  const selected = list.find((item) => item.id === activeId) || list[0];
  const messages = useListChatMessages(selected?.id || '', { query: { enabled: !!selected?.id, queryKey: getListChatMessagesQueryKey(selected?.id || '') } });
  const create = () => createSession.mutate({ data: { title: 'Field conversation' } }, { onSuccess: (session) => { queryClient.invalidateQueries({ queryKey: getListChatSessionsQueryKey() }); setActiveId(session.id); } });
  const submit = (event: React.FormEvent) => { event.preventDefault(); if (!draft.trim() || !selected) return; const content = draft.trim(); setDraft(''); send.mutate({ data: { sessionId: selected.id, content } }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListChatMessagesQueryKey(selected.id) }) }); };
  return <div className="fade-up"><PageHeading eyebrow="Agronomist assistant" title="Bring a question from the field." detail="A practical conversation space for crop decisions, context, and the next right action." action={<Button variant="outline" onClick={create} disabled={createSession.isPending}><Plus className="h-4 w-4" />New conversation</Button>} /><div className="grid min-h-[560px] gap-4 lg:grid-cols-[280px_1fr]"><Panel title="Conversations" eyebrow={`${list.length} saved`} action={<button onClick={create} className="rounded-lg p-1.5 text-primary hover:bg-muted" aria-label="Create conversation" data-testid="button-create-chat-session"><Plus className="h-4 w-4" /></button>}><div className="space-y-1">{sessions.isLoading ? <LoadingState rows={3} /> : list.length === 0 ? <div className="py-8 text-center"><MessageCircle className="mx-auto h-6 w-6 text-muted-foreground" /><p className="mt-3 text-xs text-muted-foreground">No conversations yet.</p><Button className="mt-4 w-full" onClick={create}>Start one</Button></div> : list.map((session) => <button key={session.id} onClick={() => setActiveId(session.id)} className={cn('w-full rounded-xl px-3 py-3 text-left transition-colors', selected?.id === session.id ? 'bg-secondary' : 'hover:bg-muted')} data-testid={`button-chat-session-${session.id}`}><p className="truncate text-sm font-bold">{session.title}</p><p className="mt-1 truncate text-[11px] text-muted-foreground">{session.farm || 'All fields'} · {fmtDate(session.updatedAt)}</p></button>)}</div></Panel><section className="surface flex min-h-[560px] flex-col overflow-hidden rounded-2xl">{selected ? <><div className="flex items-center justify-between border-b border-border px-5 py-4"><div><p className="text-sm font-bold">{selected.title}</p><p className="mt-1 flex items-center gap-1.5 text-xs text-muted-foreground"><span className="h-1.5 w-1.5 rounded-full bg-primary" />Context: {selected.farm || 'your workspace'}</p></div><CircleHelp className="h-4 w-4 text-muted-foreground" /></div><div className="scrollbar-thin flex-1 space-y-4 overflow-y-auto p-5">{messages.isLoading ? <LoadingState rows={3} /> : ((messages.data as ChatMessage[] | undefined) || []).length === 0 ? <div className="flex h-full min-h-72 flex-col items-center justify-center text-center"><div className="grid h-12 w-12 place-items-center rounded-2xl bg-primary/10 text-primary"><Sprout className="h-6 w-6" /></div><p className="mt-4 font-display text-2xl">What are you seeing?</p><p className="mt-2 max-w-xs text-sm text-muted-foreground">Ask about a crop, a soil result, or what needs attention this week.</p></div> : (messages.data as ChatMessage[]).map((message) => <div key={message.id} className={cn('flex', message.role === 'user' ? 'justify-end' : 'justify-start')} data-testid={`message-${message.id}`}><div className={cn('max-w-[80%] rounded-2xl px-4 py-3 text-sm leading-relaxed', message.role === 'user' ? 'rounded-br-md bg-primary text-primary-foreground' : 'rounded-bl-md bg-muted text-foreground')}><p>{message.content}</p><p className={cn('mt-2 text-[10px]', message.role === 'user' ? 'text-primary-foreground/60' : 'text-muted-foreground')}>{new Date(message.createdAt).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })}</p></div></div>)}</div><form onSubmit={submit} className="border-t border-border p-4"><div className="flex items-end gap-2 rounded-xl border border-input bg-background p-2 focus-within:ring-4 focus-within:ring-primary/10"><textarea value={draft} onChange={(event) => setDraft(event.target.value)} rows={2} placeholder="Ask your agronomist assistant..." className="max-h-28 flex-1 resize-none bg-transparent px-2 py-1 text-sm outline-none" data-testid="textarea-chat-message" /><button type="submit" disabled={!draft.trim() || send.isPending} className="grid h-9 w-9 shrink-0 place-items-center rounded-lg bg-primary text-primary-foreground disabled:opacity-40" aria-label="Send message" data-testid="button-send-chat-message"><Send className="h-4 w-4" /></button></div></form></> : <div className="grid flex-1 place-items-center p-8 text-center"><div><MessageCircle className="mx-auto h-8 w-8 text-muted-foreground" /><p className="mt-3 font-semibold">Start a conversation</p><p className="mt-1 text-sm text-muted-foreground">Create a session to talk through a field decision.</p></div></div>}</section></div></div>;
}

function Analytics() {
  const dashboard = useGetDashboard();
  const data = dashboard.data as DashboardSummary | undefined;
  if (dashboard.isLoading) return <LoadingState rows={5} />;
  if (dashboard.isError || !data) return <ErrorState retry={() => dashboard.refetch()} />;
  const maxYield = Math.max(...(data.yieldData || []).map((item) => item.value), 1);
  return <div className="fade-up"><PageHeading eyebrow="Field analytics" title="Patterns worth acting on." detail="A calm view of the numbers behind your next crop decision." /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Soil readiness" value={data.soilScore} suffix="/ 100" trend="↑ 4 pts this month" /><Metric label="Avg yield potential" value={`${Math.round((data.yieldData || []).reduce((sum, item) => sum + item.value, 0) / Math.max(data.yieldData?.length || 1, 1))}`} suffix="%" tone="blue" trend="Across monitored crops" /><Metric label="Nutrient balance" value="78" suffix="/ 100" tone="amber" trend="2 fields to review" /><Metric label="Risk signals" value={data.activeAlerts} trend="Open alerts" /></div><div className="mt-4 grid gap-4 lg:grid-cols-2"><Panel title="Yield outlook by crop" eyebrow="Potential vs. target"><div className="space-y-5">{(data.yieldData || []).map((item) => <div key={item.label}><div className="mb-2 flex justify-between text-sm"><span className="font-semibold">{item.label}</span><span className="font-mono text-xs text-muted-foreground">{item.value}%</span></div><div className="relative h-8 rounded-lg bg-muted"><div className="absolute inset-y-0 left-0 rounded-lg bg-primary/80" style={{ width: `${item.value / maxYield * 100}%` }} /><div className="absolute inset-y-0 border-l border-dashed border-accent" style={{ left: `${item.target / maxYield * 100}%` }} /><span className="absolute right-2 top-2 text-[10px] font-bold text-muted-foreground">target {item.target}%</span></div></div>)}</div></Panel><Panel title="Nutrient balance" eyebrow="Current readings vs. target"><div className="space-y-5">{(data.nutrientData || []).map((item) => <div key={item.label}><div className="mb-2 flex justify-between text-sm"><span className="font-semibold">{item.label}</span><span className="font-mono text-xs text-muted-foreground">{item.value} / {item.target}</span></div><div className="h-2 rounded-full bg-secondary"><div className="h-full rounded-full bg-accent" style={{ width: `${Math.min(item.value / item.target * 100, 100)}%` }} /></div></div>)}</div><div className="mt-7 rounded-xl bg-muted/70 p-4"><div className="flex gap-3"><FlaskConical className="h-5 w-5 shrink-0 text-primary" /><p className="text-xs leading-relaxed text-muted-foreground">Nitrogen is running slightly below target across two monitored fields. Review the latest soil samples before the next feeding window.</p></div></div></Panel></div><Panel title="Risk and weather signals" eyebrow="Operational context" action={<Link href="/" className="text-xs font-bold text-primary" data-testid="link-analytics-overview">Back to overview</Link>}><div className="grid gap-3 sm:grid-cols-3"><div className="rounded-xl border border-accent/20 bg-accent/10 p-4"><CloudRain className="h-5 w-5 text-[#9a6116]" /><p className="mt-5 text-sm font-bold">Rain window ahead</p><p className="mt-1 text-xs leading-relaxed text-muted-foreground">{data.weather.rainChance}% chance in the next forecast period.</p></div><div className="rounded-xl border border-primary/15 bg-primary/5 p-4"><Droplets className="h-5 w-5 text-primary" /><p className="mt-5 text-sm font-bold">Moisture holding</p><p className="mt-1 text-xs leading-relaxed text-muted-foreground">Most fields are inside their target moisture bands.</p></div><div className="rounded-xl border border-chart-3/20 bg-chart-3/10 p-4"><Wind className="h-5 w-5 text-chart-3" /><p className="mt-5 text-sm font-bold">Watch wind stress</p><p className="mt-1 text-xs leading-relaxed text-muted-foreground">Keep an eye on exposed young growth this week.</p></div></div></Panel></div>;
}

function Settings() {
  const health = useHealthCheck();
  const [saved, setSaved] = useState(false);
  return <div className="mx-auto max-w-4xl fade-up"><PageHeading eyebrow="Workspace settings" title="Set up your field notebook." detail="Keep AgriMind aligned with the way you work, measure, and communicate." /><div className="grid gap-4 lg:grid-cols-[1fr_280px]"><div className="space-y-4"><Panel title="Profile" eyebrow="How you appear in the workspace"><div className="grid gap-4 sm:grid-cols-2"><label className="block"><span className="mb-1.5 block text-xs font-bold text-muted-foreground">Name</span><input defaultValue="Jordan Mitchell" className="h-11 w-full rounded-xl border border-input bg-background px-3 text-sm" data-testid="input-settings-name" /></label><label className="block"><span className="mb-1.5 block text-xs font-bold text-muted-foreground">Role</span><input defaultValue="Farm manager" className="h-11 w-full rounded-xl border border-input bg-background px-3 text-sm" data-testid="input-settings-role" /></label></div></Panel><Panel title="Preferences" eyebrow="Make each readout useful"><div className="space-y-5"><label className="flex items-center justify-between gap-4"><div><p className="text-sm font-bold">Language</p><p className="mt-1 text-xs text-muted-foreground">Language used for generated advisories.</p></div><select className="h-10 rounded-xl border border-input bg-background px-3 text-sm" data-testid="select-settings-language"><option>English</option><option>Spanish</option><option>French</option></select></label><label className="flex items-center justify-between gap-4"><div><p className="text-sm font-bold">Area units</p><p className="mt-1 text-xs text-muted-foreground">How field size is shown throughout the app.</p></div><select className="h-10 rounded-xl border border-input bg-background px-3 text-sm" data-testid="select-settings-units"><option>Hectares</option><option>Acres</option></select></label><label className="flex items-center justify-between gap-4"><div><p className="text-sm font-bold">Field alerts</p><p className="mt-1 text-xs text-muted-foreground">Show alerts when a signal needs attention.</p></div><input type="checkbox" defaultChecked className="h-4 w-4 accent-[hsl(var(--primary))]" data-testid="checkbox-settings-alerts" /></label></div></Panel><Button onClick={() => setSaved(true)}>{saved ? <><Check className="h-4 w-4" />Saved</> : 'Save preferences'}</Button></div><Panel title="System status" eyebrow="AgriMind services"><div className="space-y-4"><div className="flex items-center justify-between"><span className="text-sm text-muted-foreground">API connection</span>{health.isLoading ? <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" /> : <StatusPill value={health.isError ? 'Unavailable' : 'Operational'} />}</div><div className="flex items-center justify-between"><span className="text-sm text-muted-foreground">Field sync</span><StatusPill value="Operational" /></div><div className="flex items-center justify-between"><span className="text-sm text-muted-foreground">Advisory engine</span><StatusPill value="Operational" /></div></div><div className="mt-6 border-t border-border pt-4"><p className="font-mono text-[10px] text-muted-foreground">AGRIMIND / BUILD 0.1.0</p></div></Panel></div></div>;
}

function NotFound() {
  return <div className="grid min-h-[70vh] place-items-center"><div className="text-center"><div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-secondary text-primary"><Search className="h-6 w-6" /></div><p className="eyebrow mt-5 text-primary">Field not found</p><h1 className="mt-2 font-display text-4xl">This page is out of bounds.</h1><p className="mx-auto mt-3 max-w-sm text-sm leading-relaxed text-muted-foreground">The path you followed does not point to a field in this workspace.</p><Link href="/" className="mt-6 inline-flex rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground" data-testid="link-not-found-home">Return to overview</Link></div></div>;
}

function Router() {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}><AppShell><Switch><Route path="/" component={Dashboard} /><Route path="/farms" component={Farms} /><Route path="/farms/:farmId" component={FarmDetail} /><Route path="/advisory/new" component={NewAdvisory} /><Route path="/advisories" component={Advisories} /><Route path="/advisories/:advisoryId" component={AdvisoryDetail} /><Route path="/assistant" component={Assistant} /><Route path="/analytics" component={Analytics} /><Route path="/settings" component={Settings} /><Route component={NotFound} /></Switch></AppShell></ErrorBoundary>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;